action Admit = all {
  s.spc == "admit",
  any {
    all {
      MayDeny,
      s' = {
        ...s,
        phase: "failed",
        spc: "done"
      }
    },
    s' = {
      ...s,
      spc: "wait",
      hpc: "running"
    }
  }
}

action HandlerEmit = all {
  s.hpc == "running",
  s.emitted < InHandler,
  s' = receive({
    ...s,
    emitted: s.emitted + 1
  }, s.emitted + 1)
}

action HandlerReturn = {
  nondet o = Outcomes.oneOf()
  all {
    s.hpc == "running",
    s.emitted == InHandler,
    s' = {
      ...s,
      outcome: o,
      hpc: "returned"
    }
  }
}

action LateEmit = all {
  s.hpc == "returned",
  s.emitted < N,
  s' = receive({
    ...s,
    emitted: s.emitted + 1
  }, s.emitted + 1)
}

action Settle = all {
  s.spc == "wait",
  s.hpc == "returned",
  s' = if (Set("invalid", "throw").contains(s.outcome)) {
    ...s,
    phase: "failed",
    buffer: [],
    spc: "done"
  } else if (s.outcome == "replyFailure") {
    ...s,
    phase: "settled",
    buffer: [],
    spc: "done"
  } else {
    ...s,
    phase: "settled",
    chain: s.chain.concat(s.buffer),
    target: s.delivered.length() + s.chain.length() + s.buffer.length(),
    spc: "drain"
  }
}

action Deliver = all {
  not(s.busy),
  s.chain.length() > 0,
  s' = {
    ...s,
    delivered: s.delivered.append(s.chain.head()),
    chain: s.chain.tail(),
    busy: true
  }
}

action TransportSettle = all {
  s.busy,
  s' = {
    ...s,
    busy: false
  }
}

action Drained = all {
  s.spc == "drain",
  s.delivered.length() > s.target or (s.delivered.length() == s.target and not(s.busy)),
  s' = {
    ...s,
    spc: "done"
  }
}

action step = any {
  nextStep,
  s' = s
}

action purge = all {
  s.active.exists(t => stale(t)),
  remove(s.active.filter(t => stale(t))),
}

action step = any {
  tick, purge, s' = s,
  { nondet t = Traces.oneOf() any { record(t), deleteTrace(t) } },
  { nondet ownerRun = Runs.oneOf()
    nondet target = Traces.union(Set("")).oneOf()
    any { enrich(ownerRun, target), finalizeRun(ownerRun) }
  },
}

action init = s' = { runs: emptyRuns, phase: "idle", active: "a", base: 0,
  received: [], requested: "none", saved: "none", session: "none",
  failed: false }

action register(runId: str): bool = all {
  s.phase == "idle",
  s' = { ...s, runs: s.runs.set(runId, { ...s.runs.get(runId), session: "saved" }) },
}

action clear(runId: str): bool = all {
  s.phase == "idle",
  s' = { ...s, runs: s.runs.set(runId, emptyRun) },
}

action stop = all {
  s.phase == "idle",
  s' = { ...s, runs: emptyRuns },
}

action deliver = all {
  s.phase == "original",
  s' = { ...s, phase: if (s.failed) "report" else "idle",
    received: s.received.append(s.runs.get(s.active).seq) },
}

action step = {
  nondet runId = Runs.oneOf()
  nondet requested = Set("caller", "none").oneOf()
  nondet failed = Set(false, true).oneOf()
  any { register(runId), clear(runId), stop, admit(runId, requested, failed), drain, s' = s }
}

action init = s' = {
  registrations: Channels.mapBy(_ => { generation: 0, active: 0 }),
  lastHeartbeat: "none", indicator: "none", operation: "init",
  channel: "event", handle: 0, previous: 0,
}

action deliverPeer = all {
  s.operation == "self-detach",
  s' = { ...s, operation: "peer-delivered" },
}

action heartbeat(status: str): bool = all {
  s.operation != "self-detach",
  s' = { ...s, operation: "heartbeat",
    lastHeartbeat: status, indicator: if (status == "failed") "error" else "alert" },
}

action stop = all {
  s.operation != "self-detach",
  s' = { ...s, operation: "stop", lastHeartbeat: "none",
    indicator: "none", registrations: Channels.mapBy(channel =>
      { ...s.registrations.get(channel), active: 0 }) },
}

action step = {
  nondet channel = Channels.oneOf()
  nondet handle = Set(1, 2, 3).oneOf()
  nondet status = Heartbeats.oneOf()
  any {
    subscribe(channel), detach(channel, handle), heartbeat(status), stop,
    closeFromCallback, deliverPeer, s' = s,
  }
}

action Fire = all {
  s.timer == "armed",
  s' = {
    ...s,
    timer: "fired",
    tHas: s.inMap,
    inMap: false,
    tpc: if (s.inMap) "getTask" else "done"
  }
}

action TGetTask = all {
  s.tpc == "getTask",
  s' = if (s.taskExists) {
    ...s,
    tpc: "onTimeout",
    toRuns: s.toRuns + 1
  } else {
    ...s,
    tpc: "resolve"
  }
}

action TCallbackDone = all {
  s.tpc == "onTimeout",
  s' = {
    ...s,
    tpc: "resolve"
  }
}

action TCallbackFails = all {
  CanFail,
  s.tpc == "onTimeout",
  s' = settle({
    ...s,
    tpc: "done",
    inMap: false
  }, "rejected")
}

action TResolve = all {
  s.tpc == "resolve",
  s' = settle({
    ...s,
    tpc: "deleteTask"
  }, "timedOut")
}

action TDelete = all {
  s.tpc == "deleteTask",
  s' = {
    ...s,
    taskExists: false,
    tpc: "done"
  }
}

action Deliver(i: str): bool = all {
  s.spc.get(i) == "idle",
  s.taskExists,
  s' = {
    ...s,
    spc: s.spc.set(i, "getTask")
  }
}

action SGetTask(i: str): bool = all {
  s.spc.get(i) == "getTask",
  s' = if (not(s.taskExists)) {
    ...s,
    spc: s.spc.set(i, "deleteTask")
  } else {
    ...s,
    sHas: s.sHas.set(i, s.inMap),
    inMap: false,
    timer: if (s.inMap and s.timer == "armed") "cleared" else s.timer,
    spc: s.spc.set(i, if (s.inMap) "onSelect" else if (s.stopped) "deleteTask" else "done"),
    selRuns: if (s.inMap) s.selRuns + 1 else s.selRuns
  }
}

action SCallbackDone(i: str): bool = all {
  s.spc.get(i) == "onSelect",
  s' = settle({
    ...s,
    spc: s.spc.set(i, "deleteTask")
  }, "selected")
}

action SCallbackFails(i: str): bool = all {
  CanFail,
  s.spc.get(i) == "onSelect",
  s' = settle({
    ...s,
    spc: s.spc.set(i, "done")
  }, "rejected")
}

action SDelete(i: str): bool = all {
  s.spc.get(i) == "deleteTask",
  s' = {
    ...s,
    taskExists: false,
    spc: s.spc.set(i, "done")
  }
}

action Cancel = all {
  s.cpc == "idle",
  s' = {
    ...cancel(s),
    cpc: "deleteTask"
  }
}

action CancelDelete = all {
  s.cpc == "deleteTask",
  s' = {
    ...s,
    taskExists: false,
    cpc: "done"
  }
}

action Stop = all {
  not(s.stopped),
  s' = {
    ...cancel(s),
    stopped: true
  }
}

action SelectionStep = {
  nondet i = Selectors.oneOf()
  any {
    Deliver(i),
    SGetTask(i),
    SCallbackDone(i),
    SCallbackFails(i),
    SDelete(i)
  }
}

action step = any {
  nextStep,
  s' = s
}

action init = s' = {
  stopped: false, retired: false, replacement: false,
  phase: "idle", task: false, result: "none"
}

action Admit = all {
  not(s.stopped), s.phase == "idle",
  s' = { ...s, phase: "creating" }
}

action BeginList = all {
  not(s.stopped), s.phase == "idle",
  s' = { ...s, phase: "listing" }
}

action ListSettles = all {
  s.phase == "listing",
  s' = { ...s, phase: "done" }
}

action WriteDone = all {
  s.phase == "creating",
  s' = { ...s, phase: "publish", task: true }
}

action WriteFailed = all {
  s.phase == "creating",
  s' = { ...s, phase: "done", result: "rejected" }
}

action Publish = all {
  s.phase == "publish",
  s' = { ...s, phase: if (s.stopped) "cleanup" else "pending" }
}

action Cleanup = all {
  s.phase == "cleanup",
  s' = { ...s, phase: "done", task: false, result: "rejected" }
}

action BeginSelection = all {
  not(s.stopped), s.phase == "pending",
  s' = { ...s, phase: "selectionRead" }
}

action BeginTimeout = all {
  not(s.stopped), s.phase == "pending",
  s' = { ...s, phase: "timeoutRead" }
}

action ReadSelection = all {
  s.phase == "selectionRead",
  s' = { ...s, phase: if (s.stopped) "selectDelete" else "selectCallback" }
}

action SelectionReadFails = all {
  s.phase == "selectionRead",
  s' = { ...s, phase: if (s.stopped) "done" else "pending" }
}

action ReadTimeout = all {
  s.phase == "timeoutRead",
  s' = { ...s, phase: "timeoutCallback" }
}

action CallbackDone = all {
  Set("selectCallback", "timeoutCallback").contains(s.phase),
  s' = { ...s,
    phase: if (s.phase == "selectCallback") "selectDelete" else "timeoutDelete",
    result: if (s.phase == "selectCallback") "selected" else "timedOut"
  }
}

action CallbackFailed = all {
  Set("timeoutRead", "selectCallback", "timeoutCallback").contains(s.phase),
  s' = { ...s, phase: "done", result: if (s.result == "none") "rejected" else s.result }
}

action DeleteDone = all {
  Set("selectDelete", "timeoutDelete").contains(s.phase),
  s' = { ...s, phase: "done", task: false }
}

action DeleteFailed = all {
  Set("selectDelete", "timeoutDelete", "cleanup").contains(s.phase),
  s' = { ...s, phase: "done", result: if (s.result == "none") "rejected" else s.result }
}

action Cancel = all {
  s.phase == "pending",
  s' = { ...s, phase: "selectDelete", result: "cancelled" }
}

action Stop = all {
  not(s.stopped),
  s' = { ...s, stopped: true,
    phase: if (s.phase == "pending") "done" else s.phase,
    result: if (inMap) "cancelled" else s.result
  }
}

action Retire = all {
  s.stopped, not(s.retired), not(busy),
  s' = { ...s, retired: true }
}

action Replace = all {
  s.retired, not(s.replacement),
  s' = { ...s, replacement: true }
}

action step = any {
  Admit, BeginList, ListSettles, WriteDone, WriteFailed, Publish, Cleanup,
  BeginSelection, BeginTimeout, ReadSelection, SelectionReadFails, ReadTimeout,
  CallbackDone, CallbackFailed, DeleteDone, DeleteFailed, Cancel, Stop,
  Retire, Replace, s' = s
}

action Select = all {
  s.worker, s.phase == "live",
  s' = { ...s, phase: if (NeedsCallbacks) "selectEffect" else "selectDelete",
    effect: if (NeedsCallbacks) "running" else "idle" }
}

action Timeout = all {
  s.phase == "live",
  s' = { ...s, phase: if (NeedsCallbacks) "timeoutEffect" else "timeoutDelete",
    effect: if (NeedsCallbacks) "running" else "idle" }
}

action EffectDone = all {
  Set("selectEffect", "timeoutEffect").contains(s.phase),
  s' = { ...s, effect: "success",
    phase: if (s.phase == "selectEffect") "selectDelete" else "timeoutDelete" }
}

action EffectFailed = all {
  Set("selectEffect", "timeoutEffect").contains(s.phase),
  s' = { ...s, phase: "orphan", effect: "failure" }
}

action DeleteDone = all {
  Set("selectDelete", "timeoutDelete").contains(s.phase),
  s' = { ...s, phase: if (s.phase == "selectDelete") "selected" else "deleted" }
}

action DeleteFailed = all {
  Set("selectDelete", "timeoutDelete").contains(s.phase),
  s' = { ...s, phase: "orphan" }
}

action Restart = all {
  not(s.restarted), Set("live", "orphan").contains(s.phase),
  s' = { ...s, phase: "orphan", restarted: true, worker: false }
}

action RegisterSameName = all {
  s.restarted, not(s.worker),
  s' = { ...s, worker: true }
}

action SelectPersistedFree = all {
  not(NeedsCallbacks), s.worker, s.phase == "orphan",
  s' = { ...s, phase: "selectDelete" }
}

action RejectUnavailable = all {
  NeedsCallbacks, s.worker, s.phase == "orphan", s' = s
}

action Cancel = all {
  Set("live", "orphan").contains(s.phase),
  s' = { ...s, phase: "deleted" }
}

action step = any {
  Select, Timeout, EffectDone, EffectFailed, DeleteDone, DeleteFailed,
  Restart, RegisterSameName, SelectPersistedFree, RejectUnavailable, Cancel, s' = s
}

