action serialInit = s' = initial(true)

// Same-process async calls are admitted in invocation order. Distinct
// processes, or a synchronous call beside an async one, have no shared tail.

action advance(writer: int): bool = {
  nondet success = Set(false, true).oneOf()
  any { admit(writer, success), finishWrite(writer, success),
    rename(writer, success), cleanup(writer, success) }
}

action init = s' = {
  owner: "original", stopOwned: Set(),
  rooms: Rooms.mapBy(_ => { queue: List(), hydrated: false, local: List(), durable: List() }),
  calls: Calls.mapBy(_ => { phase: "idle", readOnly: false })
}

action update(id: int, call: Call, updated: Topics): bool = s' = { ...s,
  calls: s.calls.set(id, call), rooms: s.rooms.set(room(id), updated)
}

action invoke(id: int, readOnly: bool): bool = all {
  entry(id).phase == "idle",
  // Only original call 0 can be a cold read. Call 3 is invoked after reload.
  not(readOnly) or id == 0,
  id != 3 or s.owner == "replacement",
  if (permitted(id)) update(id, { phase: "queued", readOnly: readOnly },
    { ...topics(id), queue: topics(id).queue.append(id) })
  else update(id, { phase: "refused", readOnly: readOnly }, topics(id))
}

action start(id: int): bool = all {
  entry(id).phase == "queued", topics(id).queue.length() > 0,
  topics(id).queue.head() == id,
  update(id, { ...entry(id), phase: if (topics(id).hydrated) "ready" else "hydrating" }, topics(id))
}

action hydrate(id: int, ok: bool): bool = all {
  entry(id).phase == "hydrating",
  if (ok) update(id, { ...entry(id), phase: "ready" },
    { ...topics(id), hydrated: true, local: topics(id).durable })
  else update(id, { ...entry(id), phase: "failed" },
    { ...topics(id), queue: topics(id).queue.tail() })
}

action apply(id: int): bool = all {
  entry(id).phase == "ready",
  if (entry(id).readOnly) update(id, { ...entry(id), phase: "done" },
    { ...topics(id), queue: topics(id).queue.tail() })
  else update(id, { ...entry(id), phase: "writing" },
    { ...topics(id), local: topics(id).local.append(id) })
}

action persist(id: int, ok: bool): bool = all {
  entry(id).phase == "writing",
  update(id, { ...entry(id), phase: if (ok) "done" else "failed" }, {
    ...topics(id), queue: topics(id).queue.tail(),
    durable: if (ok) topics(id).local else topics(id).durable
  })
}

action beginStop = all {
  s.owner == "original",
  s' = { ...s, owner: "stopping", stopOwned: OldCalls.filter(accepted) }
}

action finishStop = all {
  s.owner == "stopping", OldCalls.forall(id => not(pending(id))),
  s' = { ...s, owner: "retired", rooms: Rooms.mapBy(r =>
    { ...s.rooms.get(r), hydrated: false, local: List() }) }
}

action replace = all {
  s.owner == "retired", s' = { ...s, owner: "replacement" }
}

action advance(id: int): bool = any {
  start(id), apply(id), { nondet ok = Bool.oneOf(); any { hydrate(id, ok), persist(id, ok) } }
}

action step = any {
  { nondet id = Calls.oneOf(); nondet readOnly = Bool.oneOf(); invoke(id, readOnly) },
  { nondet id = Calls.oneOf(); advance(id) },
  beginStop, finishStop, replace, s' = s
}

action init = {
  nondet chosen = Languages.oneOf()
  all { language' = chosen, reply' = [], status' = 0 }
}

action stutter = all {
  language' = language, reply' = reply, status' = status
}

action init = s' = {
  descriptors: Set(), handlers: routes.mapBy(_ => 0),
  phase: "idle", selectedRoute: -1, selectedOwner: 0,
  invoked: 0, result: "none"
}

action legacy(handler: int): bool = all {
  Mode != "post",
  s' = { ...s, descriptors: s.descriptors.union(Set(0)),
    handlers: s.handlers.set(0, if (Mode == "send") handler else 0) }
}

action internal(handler: int): bool = all {
  Mode == "send", s' = { ...s, handlers: s.handlers.set(0, handler) }
}

action register(r: int, handler: int): bool = s' = {
  ...s, descriptors: s.descriptors.union(Set(r)),
  handlers: if (Mode == "send" and handler == 0) s.handlers else s.handlers.set(r, handler)
}

action removeExact(r: int): bool = s' = {
  ...s, descriptors: s.descriptors.exclude(Set(r)), handlers: s.handlers.set(r, 0)
}

action dispatch = all {
  s.phase == "idle",
  s' = { ...s, selectedRoute: route, selectedOwner: owner,
    phase: if (owner == 0) "done" else if (Mode == "send") "voice"
      else if (Mode == "post") "snapshot" else "handler",
    invoked: if (owner != 0 and Mode == "hook") owner else 0,
    result: if (route == -1) "missing" else if (owner == 0) "unsupported" else "none" }
}
// Valid content passes the cosmetic gate even when its model fails. The
// source sanitizes content, then invokes the handler selected before await.

action passVoice = all {
  s.phase == "voice", s' = { ...s, phase: "handler", invoked: s.selectedOwner }
}

action invokeSnapshot = all {
  s.phase == "snapshot", s' = { ...s, phase: "handler", invoked: s.selectedOwner }
}

action resumeDispatch = any { passVoice, invokeSnapshot }
// Scenario composition only: Core message hook resolution and invocation
// are one synchronous segment; a retained post snapshot can wait to invoke.

action settle(ok: bool): bool = all {
  s.phase == "handler", s' = { ...s, phase: "done", result: if (ok) "ok" else "failed" }
}

action step = {
  nondet r = routes.oneOf()
  nondet handler = owners.oneOf()
  any {
    legacy(handler), internal(handler), register(r, 0), register(r, handler),
    removeExact(r), removeSource, dispatch, resumeDispatch, settleHandler, s' = s
  }
}

